// Generates src/shared/api/error-codes.generated.ts from ../testdata/error-codes.json.
// `node scripts/gen-error-codes.mjs --check` fails when the committed file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const src = fileURLToPath(new URL('../../testdata/error-codes.json', import.meta.url));
const out = fileURLToPath(new URL('../src/shared/api/error-codes.generated.ts', import.meta.url));

const entries = JSON.parse(readFileSync(src, 'utf8'));
const body = [
  '// GENERATED by scripts/gen-error-codes.mjs from testdata/error-codes.json. Do not edit.',
  '',
  'export const ERROR_CODES = [',
  ...entries.map((e) => `  { code: '${e.code}', status: ${e.status} },`),
  '] as const;',
  '',
  "export type ErrorCode = (typeof ERROR_CODES)[number]['code'];",
  '',
].join('\n');

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(out, 'utf8');
  } catch {
    // missing file counts as stale
  }
  if (current !== body) {
    console.error('error-codes.generated.ts is stale: run `npm run gen:error-codes`');
    process.exit(1);
  }
} else {
  writeFileSync(out, body);
}
